logAnalyticsSignals.queryText:
let resource = '__RESOURCE_ID__';
let flowing = toscalar(DatabricksJobs | where TimeGenerated > ago(1d) and _ResourceId =~ resource | count) > 0;
DatabricksJobs
| where TimeGenerated > ago(1h) and _ResourceId =~ resource
| summarize FailedRuns = countif(ActionName == 'runFailed')
| where flowing
